var body = {};
try { body = pm.response.json() || {}; } catch (e) { /* respuesta no JSON */ }
var lista = Array.isArray(body.data) ? body.data : [];
var trx = pm.collectionVariables.get('trxMulticanal');
var deLaTrx = lista.filter(function (n) { return (n.mensaje || '').indexOf(trx) !== -1; });

pm.test('Status 200', function () {
    pm.response.to.have.status(200);
});

pm.test('Existen exactamente dos entregas registradas para TRX-009', function () {
    pm.expect(deLaTrx.length).to.eql(2);
});

pm.test('Los canales registrados para TRX-009 son push y email', function () {
    var canales = deLaTrx.map(function (n) { return n.canal; });
    pm.expect(canales).to.include('push');
    pm.expect(canales).to.include('email');
});

pm.test('Ambos canales quedan en un estado de entrega valido', function () {
    var ids = [
        pm.collectionVariables.get('notifIdMulticanalPush'),
        pm.collectionVariables.get('notifIdMulticanalEmail')
    ];
    ids.forEach(function (id) {
        var n = lista.filter(function (x) { return String(x.id) === id; })[0];
        pm.expect(n, 'Falta la notificacion id=' + id).to.not.be.undefined;
        pm.expect(['enviada', 'pendiente']).to.include(n.estado);
    });
});

pm.test('Ambas entregas de TRX-009 respetan el contrato Notificacion completo', function () {
    deLaTrx.forEach(function (n) {
        pm.expect(n).to.include.keys('id', 'usuario_id', 'canal', 'asunto', 'mensaje', 'leido', 'estado', 'created_at');
    });
});

