const postRequest = {
    url: pm.variables.get('baseUrl') + '/api/v1/notificaciones',
    method: 'POST',
    header: {
        'Content-Type': 'application/json',
        'x-api-key': pm.variables.get('apiKey')
    },
    body: {
        mode: 'raw',
        raw: JSON.stringify({
            usuarioId: Number(pm.collectionVariables.get('usuarioId')),
            canal: 'push',
            asunto: 'Validacion SQL - PATCH leer',
            mensaje: 'Fixture creada para validar el patron SQL sobre PATCH /leer.'
        })
    }
};

pm.sendRequest(postRequest, (err, res) => {
    if (err) {
        console.error('No se pudo crear la notificacion fixture:', err);
        return;
    }
    const id = res.json().data.id;
    pm.collectionVariables.set('notifIdSql', id);

    const sqlRequest = utils.bodySqlRest(
        'SELECT id, leido FROM notificaciones WHERE id = $1',
        [id]
    );
    pm.sendRequest(sqlRequest, (err2, res2) => {
        if (err2) {
            console.error('Pre-request SQL check fallo:', err2);
            return;
        }
        const row = (res2.json().data || [])[0];
        console.log('Precondicion - leido antes del PATCH:', row && row.leido);
    });
});

pm.test('Status 200 - notificacion marcada como leida', () => {
    pm.response.to.have.status(200);
});

const body = pm.response.json();
pm.test('La respuesta confirma leido = true', () => {
    pm.expect(body.data.leido).to.eql(true);
});

const id = pm.collectionVariables.get('notifIdSql');

const sqlRequest = utils.bodySqlRest(
    'SELECT id, leido FROM notificaciones WHERE id = $1',
    [id]
);
pm.sendRequest(sqlRequest, (err, res) => {
    pm.test('La BD confirma leido = true tras el PATCH', () => {
        if (err) throw err;
        const row = res.json().data[0];
        pm.expect(row, 'no se encontro la notificacion en la BD').to.not.be.undefined;
        pm.expect(row.leido).to.eql(true);
    });
});

pm.collectionVariables.set('idInexistente', 99999999);

const sqlRequest = utils.bodySqlRest('SELECT COUNT(*) AS total FROM notificaciones WHERE leido = true');
pm.sendRequest(sqlRequest, (err, res) => {
    if (err) {
        console.error('Pre-request SQL check fallo:', err);
        return;
    }
    pm.variables.set('totalLeidasAntes', res.json().data[0].total);
});

pm.test('Status 404 - recurso no encontrado', () => {
    pm.response.to.have.status(404);
});

const sqlRequest = utils.bodySqlRest('SELECT COUNT(*) AS total FROM notificaciones WHERE leido = true');
pm.sendRequest(sqlRequest, (err, res) => {
    pm.test('La BD no registro ningun cambio (COUNT de leidas igual antes y despues)', () => {
        if (err) throw err;
        const totalDespues = res.json().data[0].total;
        pm.expect(Number(totalDespues)).to.eql(Number(pm.variables.get('totalLeidasAntes')));
    });
});
